create table if not exists public.timeline_daw_normalization_support_cases(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,summary text not null check(char_length(summary) between 3 and 500),state text not null default 'open' check(state in('open','investigating','resolved','revoked')),consented_at timestamptz not null,report_checksum text not null,bundle_checksum text not null,bundle jsonb not null,alert_ids jsonb not null default '[]',recovery_receipt_ids jsonb not null default '[]',retain_until timestamptz not null,revoked_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create index if not exists timeline_daw_normalization_support_cases_owner_session on public.timeline_daw_normalization_support_cases(owner_id,session_id,created_at desc);alter table public.timeline_daw_normalization_support_cases enable row level security;create policy timeline_daw_normalization_support_cases_owner on public.timeline_daw_normalization_support_cases for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());create table if not exists public.timeline_daw_normalization_support_case_history(id text primary key,case_id text not null references public.timeline_daw_normalization_support_cases(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,event text not null check(event in('created','note','state-changed','revoked')),before_state text,after_state text,note text not null default '',created_at timestamptz not null default now());alter table public.timeline_daw_normalization_support_case_history enable row level security;create policy timeline_daw_normalization_support_case_history_owner on public.timeline_daw_normalization_support_case_history for select to authenticated using(owner_id=auth.uid());create policy timeline_daw_normalization_support_case_history_insert_owner on public.timeline_daw_normalization_support_case_history for insert to authenticated with check(owner_id=auth.uid());
